{
  "qid": "t2i-0002-fftcg-l2-01",
  "sample_id": "0002",
  "gen_prompt": "俯视角度拍摄：一张深色木纹桌面上正在进行一场最终幻想集换式卡牌（Final Fantasy TCG）对局，五张卡牌正面朝上，按前排三张、后排两张摆放；桌面一侧有一叠扣放的卡牌作为卡组，另有一个卡牌补充包和两颗六面骰。暖黄色的台灯光线从画面左上方洒下，在桌面留下柔和的阴影。",
  "invocation": "L2",
  "knowledge_dim": "人造物体/桌游卡牌——集换式卡牌的实体形态、卡面信息要素与品牌识别（Final Fantasy TCG）",
  "fidelity_checks": [
    {
      "check": "画面主体为最终幻想集换式卡牌的实体印刷卡牌与实体补充包构成的桌面实物场景，而非电子游戏画面、屏幕UI或数字卡牌界面",
      "anchor": {"type": "direct", "constraint_refs": ["1"]},
      "rubric": {
        "tier_0": "卡牌或补充包被画成电子游戏画面、显示器内的UI或全息数字界面，或主体变成手办等其他周边而非卡牌商品",
        "tier_1": "卡牌为实体印刷品但实体感不足（无厚度、无投影、像贴在桌面上的平面图形），或补充包呈非实体的图标化形态",
        "tier_2": "卡牌、卡组与补充包均为可信的实体印刷商品，具有纸面质感、厚度与桌面投影，整体构成真实的桌面实物对局场景"
      },
      "variants_used": "多张卡牌或对战牌面＋补充包（依题面场景选取）",
      "visibility_requirement": "俯视构图下桌面物件均应可见；实体感依据投影、厚度与材质判断，若画面无投影线索则按纸面质感与边缘厚度判断",
      "weight": 1.0
    },
    {
      "check": "画面中每张可辨认的卡牌均为竖向矩形的印刷集换式卡牌形态",
      "anchor": {"type": "direct", "constraint_refs": ["2"]},
      "rubric": {
        "tier_0": "出现横向、方形、圆形或明显非卡牌形态的『卡』，或卡牌边缘呈不规则异形",
        "tier_1": "卡牌为竖向矩形但长宽比例明显失真（接近正方形或过于细长），或缺少印刷卡牌应有的卡框与圆角形态",
        "tier_2": "所有可见卡牌均为标准竖向矩形TCG卡比例（约1.4:1），带卡框与圆角，形态统一规范"
      },
      "variants_used": "无（清单未列变体）",
      "visibility_requirement": "俯视下卡牌轮廓完整可见；个别卡牌被骰子等物部分遮挡时以可辨轮廓判定，被完全遮挡的卡牌不参与本条判定",
      "weight": 1.0
    },
    {
      "check": "正面朝上卡牌的插画主题属于最终幻想系列自身的IP内容（历代角色、召唤兽、怪物、经典场景、元素水晶/属性符号、陆行鸟或莫古利任一类别）",
      "anchor": {"type": "combination", "constraint_refs": ["1", "3"]},
      "rubric": {
        "tier_0": "卡面插画与最终幻想世界观无关（如现实名人、其他作品风格的形象），或所有正面卡面均无法辨认出任何最终幻想主题内容",
        "tier_1": "部分正面卡面可辨认属最终幻想世界观（如水晶风格、日式奇幻角色造型），其余卡面内容含糊或与最终幻想无关",
        "tier_2": "每张正面朝上的卡牌插画均可辨认属最终幻想世界观，类别不限（角色/召唤兽/怪物/场景/水晶/陆行鸟莫古利均可）"
      },
      "variants_used": "覆盖全部变体：系列历代角色/召唤兽/怪物/经典场景/元素水晶属性符号/陆行鸟莫古利，任意组合均合法",
      "visibility_requirement": "俯视下五张正面卡面均应可辨插画内容；单张卡面因过小而完全无法辨认内容时，该张按tier_1计，其余可辨卡面正常判定",
      "weight": 1.0
    },
    {
      "check": "可见的正面卡面包含集换式卡牌应有的游戏信息要素（卡名、元素图标、费用或数值、卡牌类型、效果文本中的至少若干项）",
      "anchor": {"type": "direct", "constraint_refs": ["4"]},
      "rubric": {
        "tier_0": "正面卡面只有插画，完全没有卡名、图标、数值、文本等任何信息要素",
        "tier_1": "卡面含个别信息要素但残缺混乱（如有数字却无卡名与文本框，或要素互相压盖、位置错乱）",
        "tier_2": "每张正面卡面均含多项信息要素，且排布符合TCG卡面惯例（如卡名与元素图标、效果文本框、费用或数值标识各居其位）"
      },
      "variants_used": "标准边框卡面/全幅插画卡面/闪卡或促销卡面任一，均须含信息要素",
      "visibility_requirement": "文字无需可逐字读出，但文本框与要素版式须可辨；若画面分辨率导致某张卡的要素完全不可辨，该卡按tier_1计",
      "weight": 1.0
    },
    {
      "check": "卡牌或补充包上具有可将其识别为Final Fantasy TCG的视觉标识（如包装上的系列标志文字，或扣放卡牌背面的标志图形）",
      "anchor": {"type": "direct", "constraint_refs": ["5"]},
      "rubric": {
        "tier_0": "可见的补充包表面与卡牌背面均无任何FFTCG标识",
        "tier_1": "存在疑似标识（图形或外文字样）但模糊难辨，或拼写明显错误而无法识别为该游戏标志",
        "tier_2": "补充包包装面或卡组卡背上清晰呈现「FINAL FANTASY TRADING CARD GAME」字样标志或FFTCG水晶标志，可一眼识别"
      },
      "variants_used": "无（包装标识或卡背标识呈现其一即可）",
      "visibility_requirement": "题面要求补充包与一叠扣放卡组均在画面中，其可见面应可判；若两者可见面恰好均无标识呈现，按tier_0判",
      "weight": 1.0
    },
    {
      "check": "任何卡面或包装上不得出现最终幻想系列以外的其他IP专属角色或怪物形象",
      "anchor": {"type": "direct", "constraint_refs": ["6"]},
      "rubric": {
        "tier_0": "明确出现其他IP的专属角色或怪物形象（如宝可梦、游戏王等其他卡牌游戏的形象）",
        "tier_1": "未出现明确的其他IP角色，但卡框、标志等视觉体系明显照搬其他卡牌游戏，产生IP混淆",
        "tier_2": "全部卡面与包装内容均属最终幻想世界观，无任何其他IP形象或混淆性视觉体系"
      },
      "variants_used": "无",
      "visibility_requirement": "俯视下所有卡面与包装可见面均参与判定",
      "weight": 1.0
    }
  ],
  "alignment_checks": [
    {
      "check": "正面朝上的卡牌恰好为五张",
      "facet": "quantity",
      "rubric": {
        "tier_0": "正面朝上卡牌为1~2张或7张以上，与五张严重不符",
        "tier_1": "正面朝上卡牌为4张或6张（相差一张）",
        "tier_2": "恰好五张卡牌正面朝上"
      }
    },
    {
      "check": "五张正面卡牌按前排三张、后排两张的两排布局摆放，俯视下前后排清晰可辨",
      "facet": "spatial_2d",
      "rubric": {
        "tier_0": "无两排布局（如一字长排、围成一圈或散乱堆叠无序）",
        "tier_1": "呈两排但分布不符（如前排两张后排三张），或两排前后关系混乱、互相压叠",
        "tier_2": "俯视下前排三张、后排两张，两排整齐、前后关系清晰"
      }
    },
    {
      "check": "桌面配件按题面数量呈现：一叠扣放的卡牌作为卡组、一个卡牌补充包、两颗六面骰，均位于桌面",
      "facet": "quantity",
      "rubric": {
        "tier_0": "三类配件缺失任意一类，或骰子数量与两颗相差超过一颗",
        "tier_1": "三类配件齐全但某一项数量或形态不符（如骰子为一颗或三颗、卡组仅为单张不成叠）",
        "tier_2": "一叠多张扣放卡组、一个补充包、两颗六面骰全部正确呈现于桌面"
      }
    },
    {
      "check": "场景为深色木纹桌面上的俯视对局场景",
      "facet": "real_world_scene",
      "rubric": {
        "tier_0": "物件悬浮于虚空或渐变背景中、或呈现在电子界面里，无真实桌面环境",
        "tier_1": "有桌面但非深色木纹材质（如纯白或金属桌面），或视角接近平视导致桌面布局难以通览",
        "tier_2": "深色木纹桌面清晰可辨，俯视构图使全部物件布局一目了然"
      }
    }
  ],
  "quality_facets": ["physical_logic", "material_texture", "edge_clarity", "noise"],
  "aesthetic_facets": ["composition", "color_harmony", "lighting_atmosphere"],
  "leak_check": {
    "对照表": [
      {"constraint_ref": "1", "题面中是否出现": "无"},
      {"constraint_ref": "2", "题面中是否出现": "无"},
      {"constraint_ref": "3", "题面中是否出现": "无"},
      {"constraint_ref": "4", "题面中是否出现": "无"},
      {"constraint_ref": "5", "题面中是否出现": "无"},
      {"constraint_ref": "6", "题面中是否出现": "无"}
    ],
    "结论": "全为无"
  },
  "notes": "题面中『最终幻想集换式卡牌（Final Fantasy TCG）』属点名概念（允许）；『补充包』『正面朝上』『扣放』为场景状态词而非清单约束关键词，未泄漏任何约束的判定要求（实体性、竖向矩形、信息要素、标志文字、IP排除等均需模型自行调用知识）。视角刻意设为俯视，以保证卡面插画、信息要素、卡背与包装标识等检查点可见，不构成对合法画派的误杀。样本图中的SAMPLE水印及具体角色（尤娜&提达、克劳德等）未作为判分依据，避免图级观察冒充知识。题面中暖黄台灯左上光的规定由美感维度lighting_atmosphere承接，未在一致性维度重复设条。"
}
